import{_ as t,o,c as i,a0 as a}from"./chunks/framework.CrGeEOPE.js";const u=JSON.parse('{"title":"Vision & Roadmap","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://qbuem.com/qbuem-json/guide/vision.html"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://qbuem.com/qbuem-json/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guide\\",\\"item\\":\\"https://qbuem.com/qbuem-json/guide/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Vision & Roadmap\\",\\"item\\":\\"https://qbuem.com/qbuem-json/guide/vision.html\\"}]}"]]},"headers":[],"relativePath":"guide/vision.md","filePath":"guide/vision.md"}'),n={name:"guide/vision.md"};function r(s,e,d,c,l,m){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="vision-roadmap" tabindex="-1">Vision &amp; Roadmap <a class="header-anchor" href="#vision-roadmap" aria-label="Permalink to &quot;Vision &amp; Roadmap&quot;">​</a></h1><p>qbuem-json aims to be the <strong>fastest and safest single-header C++20 JSON library</strong> — dual-engine (flexible DOM + zero-tape struct mapping), with a <strong>cross-language binary</strong> story (CBOR) that few competitors match. The roadmap below is curated against three rules: every feature must be <strong>general-purpose</strong>, <strong>differentiated</strong>, and <strong>free of over-engineering</strong> (ship the smallest correct version; single-header and the performance/safety bar are non-negotiable).</p><p>The full, sourced roadmap lives in <a href="https://github.com/qbuem/qbuem-json/blob/main/ROADMAP.md" target="_blank" rel="noreferrer"><code>ROADMAP.md</code></a>.</p><h2 id="shipped-✅" tabindex="-1">Shipped ✅ <a class="header-anchor" href="#shipped-✅" aria-label="Permalink to &quot;Shipped ✅&quot;">​</a></h2><ul><li><strong>Dual engine</strong> — flat-tape SIMD DOM + <strong>Nexus Fusion</strong> (zero-tape direct JSON↔struct mapping).</li><li><strong>SIMD</strong> — AVX-512 · ARM NEON · <strong>SVE</strong> · SWAR structural indexing, with the Russ Cox (2026) unrounded-scaling float parser and Schubfach serialization.</li><li><strong>CBOR (RFC 8949)</strong> — binary codec from the same <code>QBUEM_JSON_FIELDS</code> registration, positional decode fast-path, generic/template types via <code>QBUEM_JSON_FIELDS_TPL</code>. Cross-language (e.g. JS <code>cbor-x</code>).</li><li><strong>Standards</strong> — JSON Pointer (RFC 6901), JSON Patch (RFC 6902), Merge Patch (RFC 7396), relaxed/comments parse mode, RFC 8259 well-formedness validation.</li><li><strong>Integration</strong> — <code>std::pmr</code> support; language bindings (Python/nanobind, Rust, Go); single-header, zero-dependency; continuously fuzzed + ASan/UBSan/TSan across x86-64 / aarch64 / Apple Silicon.</li></ul><h2 id="tier-1" tabindex="-1">Tier 1 <a class="header-anchor" href="#tier-1" aria-label="Permalink to &quot;Tier 1&quot;">​</a></h2><ul><li>✅ <strong>Macro-free aggregate reflection</strong> <em>(v1.14.0+, GCC/Clang)</em> — plain aggregate structs serialize/deserialize across JSON, CBOR, and the zero-tape <code>fuse&lt;T&gt;</code> (including generic and nested aggregates) with no <code>QBUEM_JSON_FIELDS</code> (field names via reflection); the macro/registration always wins, so it is purely additive. For <code>fuse&lt;T&gt;</code> the macro&#39;s compile-time <code>switch</code> is still the peak dispatch on very wide hot-path structs. Built for backend DTOs.</li><li>✅ <strong>Rich error context</strong> — <code>parse_error</code> exposes line/column + <code>format_error()</code> caret rendering <em>(v1.3.0)</em>.</li><li>✅ <strong>serde-style field attributes</strong> — enum (integer default + <code>QBUEM_JSON_ENUM</code> value names) <em>(v1.4.0)</em>, field rename <code>(member, &quot;jsonKey&quot;)</code> + skip-by-omission <em>(v1.5.0)</em>, default-on-absent (built in).</li><li>✅ <strong>NDJSON / JSON Lines</strong> streaming — <code>read_lines</code> / <code>write_lines</code>, bounded memory <em>(v1.6.0)</em>.</li><li>✅ <strong>Canonical JSON</strong> — <code>qbuem::canonicalize</code>, deterministic bytes for hashing/signing (RFC 8785-style); CBOR is canonical by construction <em>(v1.7.0)</em>.</li></ul><h2 id="tier-2-—-mid-term" tabindex="-1">Tier 2 — Mid-term <a class="header-anchor" href="#tier-2-—-mid-term" aria-label="Permalink to &quot;Tier 2 — Mid-term&quot;">​</a></h2><ul><li>✅ <strong>JSONPath (RFC 9535)</strong> — structural selectors (root, member, index, wildcard, recursive descent, slice, union) <em>(v1.8.0)</em> + filter selectors <code>[?...]</code> (comparisons, existence tests, <code>&amp;&amp;</code>/<code>||</code>/<code>!</code>, <code>length()</code>/<code>count()</code>/<code>value()</code>) <em>(v1.13.0)</em>. The I-Regexp <code>match()</code>/<code>search()</code> functions are intentionally out of scope (no regex engine in a single-header lib).</li><li>✅ <strong>WebAssembly build</strong> — <code>bindings/wasm</code>: validate / minify / canonicalize / JSONPath in the browser &amp; Node <em>(v1.9.0)</em>.</li><li>✅ <strong>SAX-style event visitor</strong> — <code>qbuem::visit</code> / <code>sax_parse</code> for transcoding &amp; inspection <em>(v1.10.0)</em>.</li><li>❌ <strong>MessagePack codec</strong> — declined: duplicative of the existing CBOR codec (both binary-JSON); not worth a second parallel codec to maintain.</li><li>❌ <strong>Runtime CPU dispatch</strong> — declined: a header-only library is recompiled per project (<code>-march=native</code> → optimal SIMD for free); baking a multi-versioned dispatcher into the core hot path is high risk for a benefit only prebuilt artifacts see. See the <a href="/qbuem-json/guide/bindings.html#portable-vs-native-builds-for-distributing-prebuilt-bindings">portable-vs-native build guide</a> instead.</li></ul><h2 id="tier-3-—-longer-term" tabindex="-1">Tier 3 — Longer-term <a class="header-anchor" href="#tier-3-—-longer-term" aria-label="Permalink to &quot;Tier 3 — Longer-term&quot;">​</a></h2><ul><li>✅ <strong>JSON diff / patch generation</strong> — <code>qbuem::diff</code> + a complete functional RFC 6902 <code>apply_patch</code> (real-time state sync) <em>(v1.11.0)</em>.</li><li>✅ <strong>Packaging + conformance</strong> — <code>find_package(qbuem_json CONFIG)</code>, Conan recipe + vcpkg port <em>(v1.11.1)</em>, and a full <a href="/qbuem-json/guide/correctness.html#jsontestsuite-conformance">JSONTestSuite conformance run</a> (283/283 mandatory cases under ASan+UBSan).</li><li>❌ <strong>JSON Schema</strong> validation — <strong>declined</strong>: not differentiated (jsoncons / blaze / valijson already do it well), an L–XL subset would bloat the single header, and known C++ shapes get <em>compile-time</em> validation from <code>fuse&lt;T&gt;</code> already. We <a href="/qbuem-json/guide/correctness.html#json-schema-validation-interop">document interop</a> instead.</li><li>❌ <strong>Schemaless On-Demand lazy cursor</strong> — <strong>declined</strong>: a simdjson parity-chase; the flat-tape DOM + <code>fuse</code> already cover our cases, and the iterator-invalidation semantics are high regression risk.</li><li>⏸️ <strong>Chunked / incremental (socket) parsing</strong> — <strong>deferred</strong>: WebSocket frames and framed CBOR are already message-delimited, so a full message arrives before parse.</li><li>⏸️ <strong>C++26 P2996 reflection backend</strong> — <strong>gated</strong> to stable compilers (~2028): macro-free registration as an <em>opt-in fast-lane</em> (the macro stays the portable default).</li></ul><p>The curated roadmap is <strong>complete as of v1.16.0</strong> — Tier 1, Tier 2, and the subset of Tier 3 that fits the library&#39;s identity are shipped (including macro-free aggregate reflection in v1.14.0, <code>read_strict&lt;T&gt;</code> strict deserialization in v1.15.0, and RFC conformance hardening verified against the official JSONPath / JCS / JSONTestSuite corpora in v1.16.0); everything else above is a conscious decline/defer/gate. Further work is demand-driven, not roadmap-driven.</p><h2 id="declined" tabindex="-1">Declined <a class="header-anchor" href="#declined" aria-label="Permalink to &quot;Declined&quot;">​</a></h2><p>Speculative or niche items we are intentionally <strong>not</strong> pursuing (would fail the guiding rules): coroutine/async parsing, intra-document multithreading, constexpr JSON parsing; JMESPath / JSONata / jq embedding (JSONPath — now with filters — covers the query need); BSON, Amazon Ion, Apache Arrow/columnar, FlatBuffers/Cap&#39;n Proto; and the old vision&#39;s &quot;Protocol Shifting (SBE/FIX)&quot;, &quot;IDL Inference&quot;, and &quot;Nexus Codegen&quot;. (SVE, language bindings, and <code>std::pmr</code> from the old vision are <strong>already shipped</strong>.)</p>',14)])])}const h=t(n,[["render",r]]);export{u as __pageData,h as default};
